<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>Maze Discovery · 24 Bots, Zero Knowledge</title>
<style>
:root{--bg:#0a0e14;--panel:#101722;--panel2:#0d1420;--line:#223042;--text:#dbe6f2;--dim:#7d8fa3;--green:#2ecc71}
*{box-sizing:border-box}
html,body{margin:0;padding:0;background:var(--bg);color:var(--text);font-family:system-ui,-apple-system,"Segoe UI",Roboto,Helvetica,Arial,sans-serif}
.app{max-width:780px;margin:0 auto;padding:22px 16px 46px}
header h1{font-size:22px;margin:0 0 5px;letter-spacing:.3px}
header h1 .thin{color:var(--dim);font-weight:400}
header .sub{margin:0 0 16px;color:var(--dim);font-size:13px;line-height:1.55}
.hud{display:flex;flex-wrap:wrap;gap:10px;align-items:stretch;margin-bottom:14px}
.stat{background:var(--panel);border:1px solid var(--line);border-radius:10px;padding:8px 14px;min-width:106px}
.stat .label{display:block;font-size:10px;letter-spacing:1.4px;color:var(--dim);text-transform:uppercase;margin-bottom:3px}
.stat .value{font-size:20px;font-weight:700;font-family:ui-monospace,SFMono-Regular,Menlo,Consolas,monospace}
.stat .unit{font-size:11px;color:var(--dim);margin-left:4px}
.controls{display:flex;gap:8px;align-items:center;flex-wrap:wrap;background:var(--panel);border:1px solid var(--line);border-radius:10px;padding:8px 12px;flex:1;min-width:280px}
button,select{background:#1a2534;color:var(--text);border:1px solid #2c3d54;border-radius:7px;padding:7px 12px;font-size:13px;cursor:pointer;font-family:inherit}
button:hover,select:hover{background:#223146;border-color:#3a5273}
button:active{transform:translateY(1px)}
#reset{border-color:#2e6f4f;background:#143324}
#reset:hover{background:#1a4530;border-color:#3f9c6d}
#maze{background:var(--panel2);border:1px solid var(--line);border-radius:12px;padding:10px;display:flex;justify-content:center}
#cv{width:654px;max-width:100%;height:auto;aspect-ratio:1/1;border-radius:6px;display:block}
#botbar{display:flex;flex-wrap:wrap;gap:6px;margin-top:12px;align-items:center}
#botbar .cap{font-size:10px;letter-spacing:1.4px;color:var(--dim);text-transform:uppercase;margin-right:4px}
.bdot{width:13px;height:13px;border-radius:50%;border:2px solid #0a0e14;flex:none}
.bdot.done{border-color:var(--green);box-shadow:0 0 7px rgba(46,204,113,.65)}
