</style>
</head>
<body>
<div class="app">
  <header>
    <h1>Maze Discovery <span class="thin">· 24 bots, zero knowledge</span></h1>
    <p class="sub">A freshly generated perfect maze (21×21 cells). Every bot must <b>discover</b> the exit by
    exploration alone — Tremaux-style depth-first search with backtracking. No bot knows the maze layout or
    the exit location in advance: no BFS, no A*, no global map anywhere in the bot logic.</p>
  </header>

  <div class="hud">
    <div class="stat"><span class="label">Completed</span><span class="value" id="completed">0</span><span class="unit">/ 24</span></div>
    <div class="stat"><span class="label">Timer</span><span class="value" id="timer" title="Ticks elapsed — freezes the instant the last bot arrives">0</span><span class="unit">ticks</span></div>
    <div class="stat"><span class="label">Seed</span><span class="value" id="seed" style="font-size:15px">—</span></div>
    <div class="controls">
      <button id="reset" title="Generate a new random maze">↻ New Maze</button>
      <button id="playpause">Pause</button>
      <button id="step" title="Advance exactly one tick">Step +1</button>
      <select id="speed" title="Simulation speed">
        <option value="4">4 ticks/s</option>
        <option value="10" selected>10 ticks/s</option>
        <option value="25">25 ticks/s</option>
        <option value="60">60 ticks/s</option>
      </select>
    </div>
  </div>

  <div id="maze"><canvas id="cv"></canvas></div>
  <div id="botbar"><span class="cap">Bots</span></div>
  <div id="status">Generating maze…</div>

  <div class="legend">
    <h2>How the bots explore</h2>
    <p>Each bot starts out knowing only the cell it stands in. On every tick it senses the walls of <em>that
    one cell</em> and steps to a neighbouring cell. Following <b>Tremaux's rule</b>, a bot never enters a
    passage it has already walked twice; when its current cell offers no un-walked passage — a dead end, or a
    branch it has fully explored — it <b>backtracks</b> through the passage it arrived by and records the
    abandoned branch in its own memory (<code>bot.deadEnds</code>), so no passage is ever traversed more than
    twice by the same bot. The 24 bots differ only in their seeded direction preferences (all 24 permutations
    of N/E/S/W), which makes them fan out through the same maze differently. The timer freezes the instant
    the last bot arrives at the exit.</p>
  </div>

  <div class="api">
    <h2>Scripting API</h2>
    <pre>game.tick(n)       advance the simulation n ticks (synchronous, deterministic)
game.reset(seed?)  new maze &amp; bots, elapsed = 0; same numeric seed ⇒ identical run
game.elapsed      ticks elapsed — stops for good at the last bot's arrival
game.size         {rows, cols}
game.spawn        {r, c}
game.exit         {r, c}
game.walls(r, c)  {n, e, s, w} wall booleans for that cell
game.bots         24 bots → .path [{r,c}…], .deadEnds [{r,c}…], .finishTick</pre>
  </div>
</div>

<script>
(() => {
  'use strict';

  /* ============================== config ============================== */
  const ROWS = 21, COLS = 21;        // perfect maze, well above the 15×15 minimum
  const CELL = 30, PAD = 12;         // rendering metrics → 654×654 canvas
  const NUM_BOTS = 24;
  const W = COLS * CELL + PAD * 2;
  const H = ROWS * CELL + PAD * 2;

  /* direction indices: 0 = N, 1 = S, 2 = E, 3 = W */
  const DIRS = [
    { dr: -1, dc: 0, key: 'n', opp: 1 },
    { dr: 1, dc: 0, key: 's', opp: 0 },
    { dr: 0, dc: 1, key: 'e', opp: 3 },
    { dr: 0, dc: -1, key: 'w', opp: 2 }
  ];

  /* ============================ seeded RNG ============================ */
  function mulberry32(a) {
    return function () {
      a |= 0; a = (a + 0x6D2B79F5) | 0;
      let t = Math.imul(a ^ (a >>> 15), 1 | a);
      t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
      return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
    };
  }

  function shuffle(arr, rng) {
    for (let i = arr.length - 1; i > 0; i--) {
      const j = (rng() * (i + 1)) | 0;
      const t = arr[i]; arr[i] = arr[j]; arr[j] = t;
    }
    return arr;
  }

  /* All 24 permutations of the four directions (Heap's algorithm). */
  function directionPermutations() {
    const out = [];
    const a = [0, 1, 2, 3];
    const swap = (i, j) => { const t = a[i]; a[i] = a[j]; a[j] = t; };
    (function gen(k) {
      if (k === 1) { out.push(a.slice()); return; }
      for (let i = 0; i < k; i++) {
        gen(k - 1);
        if (k % 2 === 0) swap(i, k - 1); else swap(0, k - 1);
      }
    })(4);
    return out;
  }

  /* ========================= maze generation ========================= */
  /* Iterative recursive backtracker → a perfect maze (a spanning tree: fully
     connected, no loops). This is world-building only. The bots never get
     access to this structure; they discover walls one cell at a time. */
  function generateMaze(rng) {
    const walls = [];
    for (let r = 0; r < ROWS; r++) {
      const row = [];
      for (let c = 0; c < COLS; c++) row.push({ n: true, e: true, s: true, w: true });
      walls.push(row);
    }
    const seen = new Uint8Array(ROWS * COLS);
    const stack = [0];
    seen[0] = 1;
    while (stack.length) {
      const cur = stack[stack.length - 1];
      const r = (cur / COLS) | 0, c = cur % COLS;
      const options = [];
      for (let d = 0; d < 4; d++) {
        const nr = r + DIRS[d].dr, nc = c + DIRS[d].dc;
        if (nr >= 0 && nr < ROWS && nc >= 0 && nc < COLS && !seen[nr * COLS + nc]) options.push(d);
      }
      if (options.length === 0) { stack.pop(); continue; }
      const d = options[(rng() * options.length) | 0];
      const nr = r + DIRS[d].dr, nc = c + DIRS[d].dc;
      walls[r][c][DIRS[d].key] = false;
      walls[nr][nc][DIRS[DIRS[d].opp].key] = false;
      seen[nr * COLS + nc] = 1;
      stack.push(nr * COLS + nc);
    }
    return walls;
  }

  /* ============================== state ============================== */
  const state = {
    seed: 0,
    walls: null,
    bots: [],
    spawn: { r: 0, c: 0 },
    exit: { r: ROWS - 1, c: COLS - 1 },
    elapsed: 0,
    running: true,
    tps: 10
  };

  function botColor(i) {
    return 'hsl(' + (i * 15) + ', ' + (86 - (i % 3) * 6) + '%, ' + (55 + (i % 2) * 13) + '%)';
  }

  /* Canonical key for the passage between two adjacent cells. */
  function passageKey(r1, c1, r2, c2) {
    return (r1 < r2 || (r1 === r2 && c1 <= c2))
      ? r1 + ',' + c1 + '|' + r2 + ',' + c2
      : r2 + ',' + c2 + '|' + r1 + ',' + c1;
  }

  function makeBots(rng) {
    /* One unique direction permutation per bot (seeded shuffle). This
       preference order is the ONLY thing that differs between bots — it is
       what makes them spread out instead of walking in lockstep. */
    const orders = shuffle(directionPermutations(), rng);
    const bots = [];
    for (let i = 0; i < NUM_BOTS; i++) {
      const bot = {
        id: i,
        color: botColor(i),
        pos: { r: state.spawn.r, c: state.spawn.c },
        path: [{ r: state.spawn.r, c: state.spawn.c }],  // every cell entered, in order
        deadEnds: [],                                    // cells this bot proved are dead
        finishTick: null                                 // tick number of arrival at the exit
      };
      /* Private internals (non-enumerable, so the public bot objects stay clean). */
      const ang = i * 2.399963229728653;                 // golden-angle cluster offset
      const rad = CELL * 0.058 * Math.sqrt(i + 0.5);
      Object.defineProperty(bot, 'dirOrder', { value: orders[i] });   // exploration preference
      Object.defineProperty(bot, 'marks', { value: new Map() });      // Tremaux marks per passage
      Object.defineProperty(bot, 'stack', { value: [{ r: state.spawn.r, c: state.spawn.c, ed: -1 }] });
      Object.defineProperty(bot, 'vi', { value: 0, writable: true }); // visual index along path
      Object.defineProperty(bot, 'ox', { value: Math.cos(ang) * rad });
      Object.defineProperty(bot, 'oy', { value: Math.sin(ang) * rad });
      bots.push(bot);
    }
    return bots;
  }

  /* ========================= bot brain (Tremaux) ========================= */
  /* One tick, one bot. The bot consults ONLY the walls of the cell it is
     standing in plus its own memory — never the maze as a whole and never
     the exit coordinates. That is what makes this discovery, not pathfinding. */
  function botStep(bot) {
    const top = bot.stack[bot.stack.length - 1];
    const r = top.r, c = top.c;
    const cell = state.walls[r][c];

    /* 1 · Forward move: take this bot's most preferred open passage that it
          has never traversed yet (Tremaux mark 0). */
    for (let k = 0; k < 4; k++) {
      const d = bot.dirOrder[k];
      if (cell[DIRS[d].key]) continue;                 // wall — sensed locally
      const nr = r + DIRS[d].dr, nc = c + DIRS[d].dc;
      const key = passageKey(r, c, nr, nc);
      if ((bot.marks.get(key) || 0) !== 0) continue;   // passage already walked
      bot.marks.set(key, 1);
      bot.stack.push({ r: nr, c: nc, ed: d });
      bot.pos = { r: nr, c: nc };
      bot.path.push({ r: nr, c: nc });
      return;
    }

    /* 2 · Dead end / fully explored branch: backtrack through the passage we
          arrived by. Its mark goes 1 → 2, so this bot never walks it again,
          and the cell being abandoned is recorded as dead in its own memory. */
    if (bot.stack.length > 1) {
      const d = DIRS[top.ed].opp;
      const nr = r + DIRS[d].dr, nc = c + DIRS[d].dc;
      const key = passageKey(r, c, nr, nc);
      bot.marks.set(key, (bot.marks.get(key) || 0) + 1);
      bot.deadEnds.push({ r: r, c: c });
      bot.stack.pop();
      bot.pos = { r: nr, c: nc };
      bot.path.push({ r: nr, c: nc });
    }
    /* A stack worn down to the spawn with nothing un-walked left would mean
       the bot explored the entire maze — impossible before reaching the exit,
       because a perfect maze is connected and the exit is one of its cells. */
  }

  /* ============================ simulation ============================ */
  function allFinished() {
    for (let i = 0; i < state.bots.length; i++) {
      if (state.bots[i].finishTick === null) return false;
    }
    return true;
  }

  /* Advance n ticks synchronously. Pure state transitions, no randomness:
     tick(1) called n times is exactly identical to tick(n). Once the last
     bot has arrived the simulation freezes — further ticks change nothing. */
  function tick(n) {
    if (n === undefined || n === null) n = 1;
    n = Math.floor(n);
    if (n > 0 && state.bots.length) {
      for (let i = 0; i < n; i++) {
        if (allFinished()) break;                       // frozen: timer must not move
        state.elapsed++;
        const t = state.elapsed;
        for (const bot of state.bots) {
          if (bot.finishTick !== null) continue;        // resting at the exit
          botStep(bot);
          if (bot.pos.r === state.exit.r && bot.pos.c === state.exit.c) {
            bot.finishTick = t;                         // arrival detection (not navigation)
          }
        }
      }
    }
    updateHUD();
    return state.elapsed;
  }

  /* New maze and fresh bots. A numeric seed reproduces the whole run. */
  function reset(seed) {
    let s;
    if (typeof seed === 'number' && isFinite(seed)) s = Math.floor(seed) >>> 0;
    else s = (Math.random() * 4294967296) >>> 0;
    state.seed = s;
    const rng = mulberry32(s);
    state.walls = generateMaze(rng);
    state.bots = makeBots(rng);
    state.elapsed = 0;
    acc = 0;
    updateHUD();
    return state.elapsed;
  }

  /* Scripted calls take over from the auto-player so that external
     tick/reset calls are exact and reproducible. */
  function pauseAutoplay() {
    if (state.running) {
      state.running = false;
      acc = 0;
      syncPlayButton();
    }
  }

  /* ========================= scripting API ========================= */
  window.game = {
    tick: function (n) { pauseAutoplay(); return tick(n); },
    reset: function (seed) { pauseAutoplay(); return reset(seed); },
    get elapsed() { return state.elapsed; },
    get size() { return { rows: ROWS, cols: COLS }; },
    get spawn() { return { r: state.spawn.r, c: state.spawn.c }; },
    get exit() { return { r: state.exit.r, c: state.exit.c }; },
    walls: function (r, c) {
      r = Number(r); c = Number(c);
      if (!state.walls || !isFinite(r) || !isFinite(c) ||
          r < 0 || r >= ROWS || c < 0 || c >= COLS) return undefined;
      const w = state.walls[Math.floor(r)][Math.floor(c)];
      return { n: w.n, e: w.e, s: w.s, w: w.w };
    },
    get bots() { return state.bots; }
  };

  /* ============================ rendering ============================ */
  const canvas = document.getElementById('cv');
  const ctx = canvas.getContext('2d');

  function setupCanvas() {
    const dpr = Math.max(1, window.devicePixelRatio || 1);
    canvas.width = Math.round(W * dpr);
    canvas.height = Math.round(H * dpr);
    ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
  }
  setupCanvas();
  window.addEventListener('resize', setupCanvas);

  /* Interpolated position: each dot glides along the bot's actual corridor
     route (its own path log), so movement is smooth, bots stay centred in
     the corridors, and they never teleport or cut through walls. */
  function visualPos(bot) {
    const path = bot.path;
    const last = path.length - 1;
    const i = Math.max(0, Math.min(bot.vi, last));
    const i0 = Math.floor(i);
    const i1 = Math.min(i0 + 1, last);
    const f = i - i0;
    const a = path[i0], b = path[i1];
    return { r: a.r + (b.r - a.r) * f, c: a.c + (b.c - a.c) * f };
  }

  function draw(now) {
    ctx.clearRect(0, 0, W, H);
    ctx.fillStyle = '#0d1420';
    ctx.fillRect(0, 0, W, H);

    /* cell floors */
    for (let r = 0; r < ROWS; r++) {
      for (let c = 0; c < COLS; c++) {
        const x = PAD + c * CELL, y = PAD + r * CELL;
        let fill = '#151f2d';
        if (r === state.exit.r && c === state.exit.c) fill = 'rgba(46,204,113,0.16)';
        else if (r === state.spawn.r && c === state.spawn.c) fill = 'rgba(88,166,255,0.12)';
        ctx.fillStyle = fill;
        ctx.fillRect(x, y, CELL, CELL);
      }
    }

    const pulse = 0.5 + 0.5 * Math.sin(now / 380);

    /* spawn ring */
    const sx = PAD + (state.spawn.c + 0.5) * CELL;
    const sy = PAD + (state.spawn.r + 0.5) * CELL;
    ctx.beginPath();
    ctx.arc(sx, sy, CELL * 0.30, 0, Math.PI * 2);
    ctx.strokeStyle = 'rgba(88,166,255,0.35)';
    ctx.lineWidth = 1.5;
    ctx.stroke();

    /* exit marker: pulsing ring + flag */
    const ex = PAD + (state.exit.c + 0.5) * CELL;
    const ey = PAD + (state.exit.r + 0.5) * CELL;
    ctx.beginPath();
    ctx.arc(ex, ey, CELL * 0.46, 0, Math.PI * 2);
    ctx.strokeStyle = 'rgba(46,204,113,' + (0.16 + 0.30 * pulse).toFixed(3) + ')';
    ctx.lineWidth = 2;
    ctx.stroke();
    ctx.beginPath();
    ctx.moveTo(ex - 3, ey + 9);
    ctx.lineTo(ex - 3, ey - 9);
    ctx.strokeStyle = '#e6eef7';
    ctx.lineWidth = 1.6;
    ctx.stroke();
    ctx.beginPath();
    ctx.moveTo(ex - 3, ey - 9);
    ctx.lineTo(ex + 9, ey - 5.5);
    ctx.lineTo(ex - 3, ey - 2);
    ctx.closePath();
    ctx.fillStyle = '#2ecc71';
    ctx.fill();

    /* walls */
    ctx.strokeStyle = '#93a9c2';
    ctx.lineWidth = 3;
    ctx.lineCap = 'round';
    ctx.beginPath();
    for (let r = 0; r < ROWS; r++) {
      for (let c = 0; c < COLS; c++) {
        const x = PAD + c * CELL, y = PAD + r * CELL;
        const w = state.walls[r][c];
        if (w.n) { ctx.moveTo(x, y); ctx.lineTo(x + CELL, y); }
        if (w.w) { ctx.moveTo(x, y); ctx.lineTo(x, y + CELL); }
        if (r === ROWS - 1 && w.s) { ctx.moveTo(x, y + CELL); ctx.lineTo(x + CELL, y + CELL); }
        if (c === COLS - 1 && w.e) { ctx.moveTo(x + CELL, y); ctx.lineTo(x + CELL, y + CELL); }
      }
    }
    ctx.stroke();

    /* bots */
    const R = CELL * 0.17;
    for (const bot of state.bots) {
      const p = visualPos(bot);
      const x = PAD + (p.c + 0.5) * CELL + bot.ox;
      const y = PAD + (p.r + 0.5) * CELL + bot.oy;
      if (bot.finishTick !== null) {
        ctx.beginPath();
        ctx.arc(x, y, R + 2.8, 0, Math.PI * 2);
        ctx.strokeStyle = 'rgba(255,255,255,' + (0.28 + 0.30 * pulse).toFixed(3) + ')';
        ctx.lineWidth = 1.4;
        ctx.stroke();
      }
      ctx.beginPath();
      ctx.arc(x, y, R, 0, Math.PI * 2);
      ctx.fillStyle = bot.color;
      ctx.fill();
      ctx.lineWidth = 1.2;
      ctx.strokeStyle = 'rgba(4,8,14,0.75)';
      ctx.stroke();
    }
  }

  /* ============================ HUD & UI ============================ */
  const elCompleted = document.getElementById('completed');
  const elTimer = document.getElementById('timer');
  const elSeed = document.getElementById('seed');
  const elStatus = document.getElementById('status');
  const elPlay = document.getElementById('playpause');
  const elSpeed = document.getElementById('speed');

  const botDots = [];
  (function buildBotbar() {
    const bar = document.getElementById('botbar');
    for (let i = 0; i < NUM_BOTS; i++) {
      const d = document.createElement('span');
      d.className = 'bdot';
      d.style.background = botColor(i);
      d.title = 'Bot ' + i;
      bar.appendChild(d);
      botDots.push(d);
    }
  })();

  function updateHUD() {
    let done = 0;
    for (const b of state.bots) if (b.finishTick !== null) done++;
    elCompleted.textContent = done;
    elTimer.textContent = state.elapsed;
    elSeed.textContent = state.seed;
    for (let i = 0; i < state.bots.length; i++) {
      botDots[i].classList.toggle('done', state.bots[i].finishTick !== null);
    }
    if (state.bots.length && done === state.bots.length) {
      elStatus.textContent = '✔ All ' + NUM_BOTS + ' bots discovered the exit — timer frozen at ' + state.elapsed + ' ticks.';
      elStatus.classList.add('done');
    } else {
      let s = done + ' of ' + NUM_BOTS + ' bots at the exit · ' + (NUM_BOTS - done) + ' still exploring';
      if (!state.running) s += ' · paused';
      elStatus.textContent = s + '…';
      elStatus.classList.remove('done');
    }
  }

  function syncPlayButton() {
    elPlay.textContent = state.running ? 'Pause' : 'Play';
  }

  elPlay.addEventListener('click', function () {
    state.running = !state.running;
    acc = 0;
    syncPlayButton();
    updateHUD();
  });

  document.getElementById('
